def report(orders, users):
    x = 0
    totals = {}
    for u in users:
        if u['active']:
            x += 1
            totals[u['id']] = 0
    for o in orders:
        if o['user_id'] in totals:
            totals[o['user_id']] += o['amount']
    avg = sum(totals.values()) / x if x else 0
    print('active users:', x)
    print('average revenue:', avg)
    top = sorted(totals.items(), key=lambda t: t[1], reverse=True)[:5]
    for uid, amount in top:
        print(uid, amount)
    return x, avg, top


def export(users, path):
    x = len([u for u in users if u['active']])
    with open(path, 'w') as f:
        f.write(f'active={x}\n')
        for u in users:
            f.write(f"{u['id']},{u['active']}\n")
    return x

server {
  listen 80;
  server_name example.com;
  root /var/www/html;
  autoindex on;
  location /admin { proxy_pass http://127.0.0.1:8080; }
  location ~ \.php$ { fastcgi_pass unix:/run/php/php-fpm.sock; include fastcgi_params; }
  location /uploads { alias /var/www/uploads/; }
  add_header Access-Control-Allow-Origin *;
  client_max_body_size 0;
}

